#include <bits/stdc++.h>
using namespace std;

const int MAXNODES = 10000;
const int MAXEDGES = 2000000;
const int INF = 0x3f3f3f3f;

int total_nodes, total_edges, max_flow, cost_value;

struct Edge
{
    int to, next, capacity, flow, cost;
} edge_list[MAXEDGES];
int head_array[MAXNODES], edge_idx;
int parent[MAXNODES], dist[MAXNODES];
bool in_queue[MAXNODES];
int total_nodes_count;

void initialize(int n)
{
    total_nodes_count = n;
    edge_idx = 0;
    memset(head_array, -1, sizeof(head_array));
}
void add_edge(int u, int v, int cap, int cst)
{
    edge_list[edge_idx].to = v;
    edge_list[edge_idx].capacity = cap;
    edge_list[edge_idx].cost = cst;
    edge_list[edge_idx].flow = 0;
    edge_list[edge_idx].next = head_array[u];
    head_array[u] = edge_idx++;
    edge_list[edge_idx].to = u;
    edge_list[edge_idx].capacity = 0;
    edge_list[edge_idx].cost = -cst;
    edge_list[edge_idx].flow = 0;
    edge_list[edge_idx].next = head_array[v];
    head_array[v] = edge_idx++;
}
bool spfa(int s, int t)
{
    queue<int> q;
    for (int i = 0; i < total_nodes_count; i++)
    {
        dist[i] = INF;
        in_queue[i] = false;
        parent[i] = -1;
    }
    dist[s] = 0;
    in_queue[s] = true;
    q.push(s);
    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        in_queue[u] = false;
        for (int i = head_array[u]; i != -1; i = edge_list[i].next)
        {
            int v = edge_list[i].to;
            if (edge_list[i].capacity > edge_list[i].flow && dist[v] > dist[u] + edge_list[i].cost)
            {
                dist[v] = dist[u] + edge_list[i].cost;
                parent[v] = i;
                if (!in_queue[v])
                {
                    in_queue[v] = true;
                    q.push(v);
                }
            }
        }
    }
    return parent[t] != -1;
}
int run_min_cost_max_flow(int s, int t, int &total_cost)
{
    int total_flow = 0;
    total_cost = 0;
    while (spfa(s, t))
    {
        int min_cap = INF;
        for (int i = parent[t]; i != -1; i = parent[edge_list[i ^ 1].to])
        {
            if (min_cap > edge_list[i].capacity - edge_list[i].flow)
                min_cap = edge_list[i].capacity - edge_list[i].flow;
        }
        for (int i = parent[t]; i != -1; i = parent[edge_list[i ^ 1].to])
        {
            edge_list[i].flow += min_cap;
            edge_list[i ^ 1].flow -= min_cap;
            total_cost += edge_list[i].cost * min_cap;
        }
        total_flow += min_cap;
    }
    return total_flow;
}

int main()
{
    cin >> n >> m >> k >> c >> d;
    initialize(MAXNODES);
    for(int i = 0; i < k; i++)
    {
        int x;
        cin >> x;
        add_edge(0, x, 1, 0);
    }
    for(int i = 0; i < 100; i++)
    {
        for(int j = 0; j < k; j++)
            add_edge(1+i*n, 9999, 1, i*c);
    }
    for(int i = 0; i < m; i++)
    {
        int u, v;
        cin >> u >> v;
        for(int j = 1; j < 100; j++)
        {
            for(int gg = 1; gg <= k; gg++)
            {
                add_edge(u+(j-1)*n, v+j*n, 1, (2*gg-1)*d);
                add_edge(v+(j-1)*n, u+j*n, 1, (2*gg-1)*d);
            }
        }
    }
    for(int i = 1; i <= n; i++)
    {
        for(int j = 1; j < 100; j++)
        {
            add_edge(i+(j-1)*n, i+j*n, k, 0);
        }
    }

    int total_cost;
    run_min_cost_max_flow(0, 9999, total_cost);
    cout << total_cost << endl;
}
